class Account(this.balance):
    def status():
        if .balance < 0:
            return "overdrawn"
        return "ok"
a = Account(-5)
b = Account(10)
assert(a.status(), "overdrawn")
[a.status(), b.status()]

class Counter:
    def __init__(self, start):
        self.count = start
    def bump(self, step):
        self.count = .count + step
        return .count
c = Counter(5)
assert(c.bump(2), 7)
c.bump(3)

class Box(w, h):
    this.w = w
    this.h = h
    if .w == .h:
        this.kind = "square"
    else:
        this.kind = "oblong"
assert(Box(2, 2).kind, "square")
[Box(2, 2).kind, Box(2, 3).kind]

